import { SubmitHandler } from 'react-hook-form';
import { useAnswerMutation } from '~/entities/community/api/use-answer-mutation';
import { useCreateCmmntyManageMutation } from '~/entities/community/api/use-create-cmmnty-manage-mutation';
import { useDeleteCmmntyManageMutation } from '~/entities/community/api/use-delete-cmmnty-manage-mutation';
import { useUpdateOneOnOneQuestionMutation } from '~/entities/community/api/use-update-one-on-one-question-mutation';
import { CommunityParams } from '~/entities/community/model/types';
import { useNavigate } from '~/shared/lib/hooks';
import { snackBar } from '~/shared/lib/toast';

export const useOnSubmit = () => {
  const { navigateBack } = useNavigate();
  const { mutateAsync: createCmmntyManage } = useCreateCmmntyManageMutation();
  const { mutateAsync: deleteCmmntyManage } = useDeleteCmmntyManageMutation();
  const { mutateAsync: answer } = useAnswerMutation();
  const { mutateAsync: updateOneOnOneQuestion } = useUpdateOneOnOneQuestionMutation();

  const callCreateCmmntyManage: SubmitHandler<CommunityParams> = async (param) => {
    try {
      await createCmmntyManage(param);
      navigateBack();
    } catch (e: any) {
      const datas = e.response?.data || {};
      snackBar(datas?.message);
    }
  };

  const callModifyCmmntyManage: SubmitHandler<CommunityParams> = async (param) => {
    try {
      if (param.nttManageId) {
        await callUpdateOneOnOneQuestion(param);
      } else {
        await createCmmntyManage(param);
      }
      navigateBack();
    } catch (e: any) {
      const datas = e.response?.data || {};
      snackBar(datas?.message);
    }
  };

  const callDeleteCmmntyManage: SubmitHandler<CommunityParams> = async (param) => {
    try {
      await deleteCmmntyManage(param);

      return true;
    } catch (e: any) {
      const datas = e.response?.data || {};
      snackBar(datas?.message);
      return false;
    }
  };

  const callAnswer: SubmitHandler<CommunityParams> = async (param) => {
    try {
      await answer(param);
      return true;
    } catch (e: any) {
      const datas = e.response?.data || {};
      snackBar(datas?.message);
      return false;
    }
  };

  const callUpdateOneOnOneQuestion: SubmitHandler<CommunityParams> = async (param) => {
    try {
      await updateOneOnOneQuestion(param);
      return true;
    } catch (e: any) {
      const datas = e.response?.data || {};
      snackBar(datas?.message);
      return false;
    }
  };

  return {
    callCreateCmmntyManage,
    callDeleteCmmntyManage,
    callAnswer,
    callUpdateOneOnOneQuestion,
    callModifyCmmntyManage,
  };
};
