import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CommunityParams } from '~/entities/community/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updateOneOnOneQuestion = (tbCmmntyMastr: CommunityParams) => {
  return resultify(
    axios.post<any>(`${API_URLS.cmmntyManage('updateOneOnOneQuestion')}`, {
      tbCmmntyMastr,
    }),
  );
};

export const useUpdateOneOnOneQuestionMutation = (
  options?: MutationOptions<CommunityParams, CBDCAxiosError, CommunityParams>,
) => {
  const mutation = useMutation<CommunityParams, CBDCAxiosError, CommunityParams>({
    ...options,
    mutationFn: (tbCmmntyMastr: CommunityParams) => updateOneOnOneQuestion(tbCmmntyMastr),
  });

  return {
    ...mutation,
  };
};
